import { render, screen, fireEvent, waitFor, act } from '@testing-library/react';

describe('Counter', () => {
  it('renders with initial value', () => {
    render(<Counter initial={5} />);
    expect(screen.getByText('5')).toBeInTheDocument();
  });

  it('increments on button click', () => {
    render(<Counter initial={0} />);
    fireEvent.click(screen.getByText('+'));
    expect(screen.getByText('1')).toBeInTheDocument();
  });

  it('decrements on button click', () => {
    render(<Counter initial={5} />);
    fireEvent.click(screen.getByText('-'));
    expect(screen.getByText('4')).toBeInTheDocument();
  });

  it('resets to initial value', () => {
    render(<Counter initial={10} />);
    fireEvent.click(screen.getByText('+'));
    fireEvent.click(screen.getByText('+'));
    fireEvent.click(screen.getByText('Reset'));
    expect(screen.getByText('10')).toBeInTheDocument();
  });
});

describe('RegistrationForm', () => {
  it('shows validation errors on empty submit', async () => {
    render(<RegistrationForm />);
    fireEvent.click(screen.getByText('Register'));
    expect(await screen.findByText('Name is required')).toBeInTheDocument();
    expect(await screen.findByText('Valid email required')).toBeInTheDocument();
  });

  it('submits successfully with valid data', async () => {
    const consoleSpy = jest.spyOn(console, 'log').mockImplementation();
    render(<RegistrationForm />);
    fireEvent.change(screen.getByLabelText('Name'), { target: { value: 'Alice' } });
    fireEvent.change(screen.getByLabelText('Email'), { target: { value: 'alice@test.com' } });
    fireEvent.change(screen.getByLabelText('Password'), { target: { value: 'password123' } });
    fireEvent.click(screen.getByText('Register'));
    await waitFor(() => {
      expect(consoleSpy).toHaveBeenCalledWith('Form submitted:', expect.any(Object));
    });
    consoleSpy.mockRestore();
  });
});

describe('UserProfile async', () => {
  it('shows loading state initially', () => {
    global.fetch = jest.fn(() => new Promise(() => {}));
    render(<UserProfile userId={1} />);
    expect(screen.getByText('Loading...')).toBeInTheDocument();
  });

  it('displays user data after fetch', async () => {
    const mockUser = { name: 'Alice', email: 'alice@test.com' };
    global.fetch = jest.fn(() => Promise.resolve({
      json: () => Promise.resolve(mockUser),
      ok: true
    }));
    render(<UserProfile userId={1} />);
    await waitFor(() => {
      expect(screen.getByText('Alice')).toBeInTheDocument();
    });
  });

  it('shows error on failed fetch', async () => {
    global.fetch = jest.fn(() => Promise.reject(new Error('Network error')));
    render(<UserProfile userId={1} />);
    await waitFor(() => {
      expect(screen.getByText(/Network error/)).toBeInTheDocument();
    });
  });
});

describe('useLocalStorage hook', () => {
  it('reads initial value from localStorage', () => {
    localStorage.getItem = jest.fn(() => '"saved"');
    function TestComponent() {
      const [value] = useLocalStorage('key', 'default');
      return <div>{value}</div>;
    }
    render(<TestComponent />);
    expect(screen.getByText('saved')).toBeInTheDocument();
  });
});
